id: S.webapp.screens
kind: requirement
fields:
  thing: thing.webapp
  title: Screens
  text: authenticated screens must share one AppShell containing exactly TopBar, PrimaryNav and RouteOutlet. PrimaryNav must contain Today, People and Settings. Counts below specify required RouteOutlet composition, excluding the shell. All private screens must show one StatePanel for loading or fatal error in place of loaded content. Forms must keep entered values after recoverable validation or network errors and render one ErrorSummary when needed.
  enabled: true
  source:
    doc: keep-in-touch-world-specification
    section: "6"
